--- src/messages.js
     1	const { tx } = require('./db');
     2	const outbox = require('./outbox');
     3	const { emit } = require('./events');
     4	const channels = require('./channels');
     5	
     6	let next = 1;
     7	
     8	function send(channelId, userId, text) {
     9	  const msg = tx((t) => {
    10	    const m = { id: 'm' + next++, channelId, userId, text, sentAt: Date.now() };
    11	    t.messages.push(m);
    12	    outbox.append(t, { type: 'message.created', id: m.id });
    13	    return m;
    14	  });
    15	  emit(channelId, 'message', { id: msg.id, userId, text, sentAt: msg.sentAt });
    16	  return msg;
    17	}
    18	
    19	function remove(channelId, id) {
    20	  if (channels.get(channelId)?.legal_hold) throw new Error('channel is under legal hold');
    21	  tx((t) => {
    22	    t.messages = t.messages.filter((m) => m.id !== id);
    23	    outbox.append(t, { type: 'message.deleted', id });
    24	  });
    25	  emit(channelId, 'message.deleted', { id });
    26	}
    27	
    28	module.exports = { send, remove };

